var canCross = function(stones) {
    if (!stones || stones.length === 0) return false;
    if (stones.length === 1) return true;

    const reachable = new Map();
    for (const position of stones) reachable.set(position, new Set());
    reachable.get(stones[0]).add(0);

    for (const position of stones) {
        for (const previousJump of reachable.get(position)) {
            for (const jump of [previousJump - 1, previousJump, previousJump + 1]) {
                if (jump > 0 && reachable.has(position + jump)) {
                    reachable.get(position + jump).add(jump);
                }
            }
        }
    }

    return reachable.get(stones[stones.length - 1]).size > 0;
};

solution.python:
class Solution:
    def canCross(self, stones: List[int]) -> bool:
        if not stones:
            return False
        if len(stones) == 1:
            return True

        reachable = {position: set() for position in stones}
        reachable[stones[0]].add(0)

        for position in stones:
            for previous_jump in reachable[position]:
                for jump in (previous_jump - 1, previous_jump, previous_jump + 1):
                    if jump > 0 and position + jump in reachable:
                        reachable[position + jump].add(jump)

        return bool(reachable[stones[-1]])
